const http = require('http');
const fs = require('fs');
const path = require('path');

const url = 'http://127.0.0.1:64534/status';
const outDir = path.join(__dirname, 'results');
const outFile = path.join(outDir, 'status.json');

http.get(url, (res) => {
  let body = '';
  res.on('data', (chunk) => { body += chunk; });
  res.on('end', () => {
    let status = res.statusCode;
    try {
      const parsed = JSON.parse(body);
      if (parsed && parsed.status !== undefined) status = parsed.status;
    } catch (e) {
      // keep HTTP status code
    }
    fs.mkdirSync(outDir, { recursive: true });
    fs.writeFileSync(outFile, JSON.stringify({ status }, null, 2));
    console.log('status:', status);
  });
}).on('error', (err) => {
  console.error('request failed:', err.message);
  process.exit(1);
});

